import AppKit

/// Pick from Canvas for the qualifier (spec §11 GR-13, owner choice 8): the
/// Qualifier section's button arms a third modal canvas mode beside the
/// chroma eyedropper and the region band (`armCanvasMode` ends the others),
/// the next click on the preview samples the picture BEHIND the selected
/// adjustment clip — rendered with the `behind` option, so the clip's own
/// grade and every canvas layer in front of it are left out — and the
/// ranges are centred on that pixel (`ColorQualifier.picked`). One undo
/// step, "Qualifier"; Esc, a second press of the button, or a selection
/// change cancels.
///
/// The pixel is re-rendered rather than read off the screen, and off the
/// main thread, for the eyedropper's reasons (`+Eyedropper`): the commit
/// that follows is OFF-EVENT, so it goes through `applyGrouped`.
extension EditorViewController {
    /// One frame composed for one pixel: its own queue, as the eyedropper's.
    private static let qualifierPickQueue = DispatchQueue(
        label: "com.kgalligan.framejob.qualifier-pick", qos: .userInitiated)

    /// The armed mode. Nil is the answer to "is the mode on".
    var qualifierPick: QualifierPickView? {
        canvasContainer.subviews.compactMap { $0 as? QualifierPickView }.first
    }

    // MARK: - Commands

    /// The section's "Pick from Canvas", sent as a command the way the
    /// chroma key's is. A second press disarms. Refused (a beep) unless every
    /// selected clip is an adjustment clip.
    @objc func pickQualifier(_ sender: Any?) {
        guard qualifierPick == nil else {
            endQualifierPick()
            return
        }
        guard let inspector = inspector, previewCanvas != nil else {
            NSSound.beep()
            return
        }
        let clips = inspector.binding.clips
        guard let first = clips.first, clips.allSatisfy({ InspectorTab.isAdjustment($0) }) else {
            NSSound.beep()
            return
        }
        let picker = QualifierPickView(clips: clips.map { $0.id }, behind: first.id)
        // One-line forwards only (app/CLAUDE.md).
        picker.onPick = { [weak self] point in self?.qualifierPicked(at: point) }
        picker.onCancel = { [weak self] in self?.endQualifierPick() }
        armCanvasMode(picker)
    }

    /// Disarms it, from Esc, a second press, a completed pick, `syncQualifierPick`
    /// and `armCanvasMode` arming another mode.
    func endQualifierPick() { dismissCanvasMode(qualifierPick) }

    /// Called from `refreshCanvas`: armed for the clips selected when it
    /// opened, it closes the moment the selection is anything else.
    func syncQualifierPick() {
        guard let picker = qualifierPick else { return }
        let current = inspector?.binding.clips.map { $0.id } ?? []
        guard current != picker.clips else { return }
        endQualifierPick()
    }

    // MARK: - The pick

    /// One click on the preview, `point` in WINDOW coordinates.
    private func qualifierPicked(at point: CGPoint) {
        guard let document = document, previewCanvas != nil, let picker = qualifierPick
        else { return }
        guard let target = pickedCanvasPixel(atWindow: point) else {
            // A click in the void is a miss, not a decision: the mode stays.
            NSSound.beep()
            return
        }
        let snapshot = document.editedProject.snapshot.canvas
        let clips = picker.clips
        let behind = picker.behind
        let hlg = snapshot.output == .hlg
        endQualifierPick()
        let project = document.editedProject
        let urls = document.mediaURLs()
        let time = document.playhead
        let graphics = GraphicRegistry.shared.snapshot(for: document.recipeKey)
        EditorViewController.qualifierPickQueue.async { [weak self] in
            let color = QualifierPick.sample(
                project: project, urls: urls, at: time, clip: behind, point: target,
                canvas: snapshot, graphics: graphics)
            DispatchQueue.main.async { self?.qualifierSampled(color, clips: clips, hlg: hlg) }
        }
    }

    /// Back on the main thread with the sampled colour: the ranges centred on
    /// it, through the binding's off-event door (an action's end when one is
    /// selected), unless the selection moved while the frame composed. `hlg`
    /// is the canvas output's, read with the click: the pass's luma weights.
    private func qualifierSampled(_ color: RGBA?, clips: [UInt32], hlg: Bool) {
        guard let inspector = inspector, let color = color else {
            NSSound.beep()
            return
        }
        let binding = inspector.binding
        guard binding.clips.map({ $0.id }) == clips else {
            NSSound.beep()
            return
        }
        let patch = binding.videoProps.qualifier.picked(QualifierSample(color, hlg: hlg))
        binding.applyGrouped("Qualifier", binding.ops(video: VideoPatch(qualifier: patch)))
    }
}

/// What a pick samples (GR-13): the frame at `at` rendered with
/// `RecipeOptions(behind: clip)` — the adjustment clip and every canvas
/// layer in front of it left out — read at `point` (canvas pixels) as the
/// eyedropper reads a pixel. An HLG project's frame is read at its code
/// values (`FrameWriter.pickable`) and not un-lifted: the qualifier works on
/// the HLG signal (spec §11 HD-13 (h)).
enum QualifierPick {
    static func sample(
        project: ReelProject, urls: [UInt32: URL], at time: Ticks, clip: UInt32,
        point: CGPoint, canvas: CanvasSnapshot, graphics: GraphicSet?
    ) -> RGBA? {
        let options = RecipeOptions(behind: clip)
        let frame = Exporter.renderFrame(
            project: project, urls: urls, at: time, maxWidth: nil, options: options,
            graphics: graphics)
        return frame.flatMap {
            CanvasEyedropperSession.color(at: point, in: FrameWriter.pickable($0), canvas: canvas)
        }
    }
}

/// Pick from Canvas's overlay: the clips it was armed for and the
/// adjustment clip whose picture behind it is sampled.
final class QualifierPickView: CanvasPickOverlay {
    let clips: [UInt32]
    let behind: UInt32

    init(clips: [UInt32], behind: UInt32) {
        self.clips = clips
        self.behind = behind
        super.init(hint: "Click to pick the colour to qualify · Esc to cancel")
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("QualifierPickView does not support NSCoder")
    }
}
                h = 60 * ((b - r) / c + 2)
            } else {
                h = 60 * ((r - g) / c + 4)
            }
        }
        hue = h
        chroma = c
        saturation = (mx > 0 ? c / mx : 0) * Self.smoothstep(0.03, 0.10, mx)
        if hlg {
            let w = InputConversions.luma2020
            luma = Double(w.x) * r + Double(w.y) * g + Double(w.z) * b
        } else {
            luma = 0.2126 * r + 0.7152 * g + 0.0722 * b
        }
    }

    /// Metal's `smoothstep`, Hermite.
    static func smoothstep(_ e0: Double, _ e1: Double, _ x: Double) -> Double {
        let t = min(max((x - e0) / (e1 - e0), 0), 1)
        return t * t * (3 - 2 * t)
    }
}

extension ColorQualifier {
    /// The chroma below which a pick has no hue (GR-13's guard's full point).
    static let pickChroma = 0.06

    /// What a pick of `s` writes (owner choice 8): hue and saturation on and
    /// centred on the pixel — a range already on keeps its width and
    /// softness; one off takes hue width 30° softness 15° and saturation
    /// ±0.15 softness 0.1 — and luma re-centred only if already on. A level
    /// range that would cross 0 or 1 is SHIFTED back inside with its width
    /// kept, so the pixel stays inside. A pixel with C below 0.06 turns hue
    /// off; Invert is unchanged.
    func picked(_ s: QualifierSample) -> ColorQualifierPatch {
        var patch = ColorQualifierPatch()
        if s.chroma < Self.pickChroma {
            patch.hue = .off
        } else {
            let width = hue?.width ?? 30
            let softness = hue?.softness ?? 15
            let center = min(max(s.hue, 0), 360)
            patch.hue = .set(QualifierHue(center: center, width: width, softness: softness))
        }
        let saturated = saturation ?? QualifierLevels(low: 0, high: 0.3, softness: 0.1)
        patch.saturation = .set(Self.centred(saturated, on: s.saturation))
        if let luma {
            patch.luma = .set(Self.centred(luma, on: s.luma))
        }
        return patch
    }

    /// `range` moved so its middle is `value`, its width and softness kept,
    /// then shifted back inside 0…1 whole.
    static func centred(_ range: QualifierLevels, on value: Double) -> QualifierLevels {
        let width = min(max(range.high - range.low, 0), 1)
        var low = value - width / 2
        low = min(max(low, 0), 1 - width)
        return QualifierLevels(low: low, high: min(low + width, 1), softness: range.softness)
    }
}
import AppKit

/// Seeing the grade (grading GR3, grading-2 G2-1 and G2-4, spec §11 GR-4,
/// GR-5, GR-10 and GR-13): View ▸ Show Ungraded, View ▸ Show Selection,
/// View ▸ Show SDR Version (hdr H-3, spec §11 HD-7, HD-14 (g)) and View ▸
/// Scopes, checkmark toggles in the preview group.
///
/// **All four are view state, per window, and none persists**: no
/// `UserDefaults` key, so a new window starts with each off (and the scopes'
/// slots at Waveform over Vectorscope) and a proof can drive them through
/// `perform_menu_item` without moving the defaults. No MCP tool mirrors them
/// or the slot picks (§7.9's Preview Quality exemption); `render_frame
/// {ungraded, selection, sdr_version, waveform, parade, vectorscope,
/// histogram}` is the capability.
///
/// **Show Ungraded, Show Selection and Show SDR Version are options on the
/// document's KEY** (`RecipeSource`,
/// spec §7.3), so it reaches exactly what composes through that key: the
/// editor's preview and the Preview Window, one player. An export, Save
/// Frame…, the eyedropper and `render_frame` mint keys of their own
/// (`Exporter`), which is why the switch cannot reach them.
///
/// **Show Selection is bound to ONE adjustment clip** (`selection` holds its
/// id): turned on for the first selected adjustment clip, rebound when the
/// selection changes to another (`syncShowSelection`, from `refreshCanvas`),
/// and turned off when no adjustment clip is selected; disabled while off
/// with none selected.
///
/// The panel and the tag stack are found by kind among `canvasContainer`'s
/// subviews, as `previewCanvas` is: the frozen base file holds no property
/// for them. The tags sit in one horizontal stack (spacing 4, hidden tags
/// detached), so "Selection" moves into the corner when "Ungraded" is off.
extension EditorViewController {
    var scopesPanel: ScopesPanelView? {
        canvasContainer.subviews.compactMap { $0 as? ScopesPanelView }.first
    }

    var seeingTags: SeeingTagStack? {
        canvasContainer.subviews.compactMap { $0 as? SeeingTagStack }.first
    }

    func previewTag(_ kind: PreviewTag) -> PreviewTagView? {
        seeingTags?.arrangedSubviews.compactMap { $0 as? PreviewTagView }.first { $0.kind == kind }
    }

    var ungradedTag: PreviewTagView? { previewTag(.ungraded) }

    var selectionTag: PreviewTagView? { previewTag(.selection) }

    var sdrVersionTag: PreviewTagView? { previewTag(.sdrVersion) }

    /// The panel at the pane's right edge, the loudness column between it
    /// and the canvas, and the tags in the void's top-left corner. Called
    /// once, from `installCanvas`. A slot the panel reveals or re-picks asks
    /// for a frame through `refreshSeeing`.
    func installSeeing(beside canvas: PreviewCanvasView) {
        let panel = ScopesPanelView()
        panel.onNeedsFrame = { [weak self] in self?.refreshSeeing() }
        let tag = SeeingTagStack(
            views: [.ungraded, .selection, .sdrVersion].map(PreviewTagView.init))
        tag.orientation = .horizontal
        tag.spacing = 4
        tag.detachesHiddenViews = true
        for view in [panel, tag] as [NSView] {
            view.translatesAutoresizingMaskIntoConstraints = false
            canvasContainer.addSubview(view)
        }
        NSLayoutConstraint.activate([
            panel.topAnchor.constraint(equalTo: canvasContainer.topAnchor),
            panel.bottomAnchor.constraint(equalTo: canvasContainer.bottomAnchor),
            panel.trailingAnchor.constraint(equalTo: canvasContainer.trailingAnchor),
            tag.topAnchor.constraint(equalTo: canvasContainer.topAnchor, constant: 4),
            tag.leadingAnchor.constraint(equalTo: canvasContainer.leadingAnchor, constant: 8),
        ])
        // The canvas's trailing edge is the loudness column's leading one, and
        // the column's trailing edge the panel's (spec §11 AU-75).
        installLoudnessPanel(between: canvas, and: panel)
    }

    // MARK: - Commands

    /// View ▸ Show Ungraded (⌃⌘U): every grade off in this window's preview.
    @objc func toggleShowUngraded(_ sender: Any?) {
        guard let document = document else { return }
        var options = RecipeSource.shared.options(for: document.recipeKey)
        options.ungraded.toggle()
        RecipeSource.shared.setOptions(options, for: document.recipeKey)
        ungradedTag?.isHidden = !options.ungraded
        refreshSeeing()
    }

    /// View ▸ Show Selection (no shortcut, spec §11 GR-13): on, bound to the
    /// first selected adjustment clip; off. The Qualifier section's switch
    /// sends the same command, and the inspector is refreshed so it follows.
    @objc func toggleShowSelection(_ sender: Any?) {
        guard let document = document else { return }
        var options = RecipeSource.shared.options(for: document.recipeKey)
        if options.selection != nil {
            options.selection = nil
        } else if let clip = firstSelectedAdjustment {
            options.selection = clip
        } else {
            NSSound.beep()
            return
        }
        showSelection(options, for: document)
    }

    /// View ▸ Show SDR Version (no shortcut, spec §11 HD-7, HD-14 (g)): this
    /// window's preview drawn as the project's SDR version — `dynamicRange`
    /// `.sdr` on the document's key, the composition recoloured BT.709 with
    /// no rebuild (`Playback.recompose`). In an SDR project no pixel changes
    /// and the tag still shows.
    @objc func toggleShowSDRVersion(_ sender: Any?) {
        guard let document = document else { return }
        var options = RecipeSource.shared.options(for: document.recipeKey)
        options.dynamicRange = options.dynamicRange == .sdr ? nil : .sdr
        RecipeSource.shared.setOptions(options, for: document.recipeKey)
        sdrVersionTag?.isHidden = options.dynamicRange != .sdr
        playback.recompose()
    }

    /// Called from `refreshCanvas`: while Show Selection is on, a selection
    /// change rebinds it to the first selected adjustment clip, or turns it
    /// off when none is selected. Nothing while it is off.
    func syncShowSelection() {
        guard let document = document else { return }
        var options = RecipeSource.shared.options(for: document.recipeKey)
        guard let bound = options.selection else { return }
        let next = firstSelectedAdjustment
        guard next != bound else { return }
        options.selection = next
        showSelection(options, for: document)
    }

    /// The first selected adjustment clip's id, or nil.
    private var firstSelectedAdjustment: UInt32? {
        (inspector?.selectedClips ?? []).first { InspectorTab.isAdjustment($0) }?.id
    }

    /// Publishes `options` on the document's key, the tag and the switch
    /// following.
    private func showSelection(_ options: RecipeOptions, for document: ProjectDocument) {
        RecipeSource.shared.setOptions(options, for: document.recipeKey)
        selectionTag?.isHidden = options.selection == nil
        refreshSeeing()
        inspector?.refresh(isLive: false)
    }

    /// View ▸ Scopes (⌃⌘W): the panel beside the preview, on or off.
    @objc func toggleScopes(_ sender: Any?) {
        guard let document = document, let panel = scopesPanel else { return }
        panel.setShown(!panel.isShown, key: document.recipeKey)
        refreshSeeing()
    }

    /// The paused frame composed again: the preview shows the switch at once,
    /// and a panel just shown gets a frame to analyse (a playing preview
    /// composes on its own).
    private func refreshSeeing() {
        playback.refreshPausedFrame()
    }

    // MARK: - Validation

    /// The half of `validateUserInterfaceItem` this file owns; nil means "not
    /// one of mine". Show Ungraded, Show SDR Version and Scopes are always
    /// enabled, like Preview Window: each is about the preview, not the
    /// timeline; Show Selection is disabled while off with no adjustment clip
    /// selected. The checkmark is the state.
    func validateSeeingAction(
        _ action: Selector, item: any NSValidatedUserInterfaceItem
    ) -> Bool? {
        switch action {
        case #selector(toggleShowUngraded(_:)):
            let on = document.map { RecipeSource.shared.options(for: $0.recipeKey).ungraded }
            (item as? NSMenuItem)?.state = on == true ? .on : .off
            return true
        case #selector(toggleShowSDRVersion(_:)):
            let on = document.map {
                RecipeSource.shared.options(for: $0.recipeKey).dynamicRange == .sdr
            }
            (item as? NSMenuItem)?.state = on == true ? .on : .off
            return true
        case #selector(toggleShowSelection(_:)):
            let on = document.flatMap {
                RecipeSource.shared.options(for: $0.recipeKey).selection
            } != nil
            (item as? NSMenuItem)?.state = on ? .on : .off
            return on || firstSelectedAdjustment != nil
        case #selector(toggleScopes(_:)):
            (item as? NSMenuItem)?.state = scopesPanel?.isShown == true ? .on : .off
            return true
        default:
            return validateSubjectsAction(action, item: item)
        }
    }
}

/// The preview's tag stack (spec §11 GR-4, GR-13, HD-14 (g)): "Ungraded",
/// "Selection", then "SDR Version", hidden tags detached. Like the tags, it
/// takes no clicks, so a gesture in the void beneath it is the canvas's.
final class SeeingTagStack: NSStackView {
    override func hitTest(_ point: NSPoint) -> NSView? { nil }
}

